mapper.select:
SELECT id, session_id, user_id, message_content, message_sent_time, read_status
FROM chat_context
WHERE id = #{id}
  AND user_id = #{userId}

SELECT id, session_id, user_id, message_content, message_sent_time, read_status
FROM chat_context
WHERE session_id = #{sessionId}
  AND user_id = #{userId}
ORDER BY message_sent_time ASC, id ASC

mapper.update:
UPDATE chat_context
SET read_status = #{readStatus}
WHERE id = #{id}
  AND user_id = #{userId}

UPDATE chat_context
SET read_status = #{readStatus}
WHERE session_id = #{sessionId}
  AND user_id = #{userId}
  AND read_status != #{readStatus}

mapper.delete:
DELETE FROM chat_context
WHERE id = #{id}
  AND user_id = #{userId}

DELETE FROM chat_context
WHERE session_id = #{sessionId}
  AND user_id = #{userId}
